import java.util.*;

class Solution {
  public List<String> addOperators(String num, int target) {
    List<String> ans = new ArrayList<>();
    build(num, target, 0, 0, 0, new StringBuilder(), ans);
    return ans;
  }

  // value: total so far; last: the last multiplicative term, so * can undo and redo it
  private void build(String num, int target, int pos, long value, long last, StringBuilder expr, List<String> ans) {
    if (pos == num.length()) {
      if (value == target) ans.add(expr.toString());
      return;
    }
    int len = expr.length();
    for (int i = pos; i < num.length(); i++) {
      if (i > pos && num.charAt(pos) == '0') break; // no leading zeros
      long cur = Long.parseLong(num.substring(pos, i + 1));
      if (pos == 0) {
        expr.append(cur);
        build(num, target, i + 1, cur, cur, expr, ans);
        expr.setLength(len);
      } else {
        expr.append('+').append(cur);
        build(num, target, i + 1, value + cur, cur, expr, ans);
        expr.setLength(len);
        expr.append('-').append(cur);
        build(num, target, i + 1, value - cur, -cur, expr, ans);
        expr.setLength(len);
        expr.append('*').append(cur);
        build(num, target, i + 1, value - last + last * cur, last * cur, expr, ans);
        expr.setLength(len);
      }
    }
  }
}
